function maxSubarrays(nums) {
  // best[i] = [smallest total score, most pieces with that total] for the first i elements.
  const n = nums.length;
  const best = [[0, 0]];
  for (let end = 1; end <= n; end++) {
    let choice = null;
    let score = -1;
    for (let start = end - 1; start >= 0; start--) {
      score &= nums[start];
      const total = best[start][0] + score;
      const pieces = best[start][1] + 1;
      if (!choice || total < choice[0] || (total === choice[0] && pieces > choice[1])) choice = [total, pieces];
    }
    best.push(choice);
  }
  return best[n][1];
}

