function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const mode = rand();
  // Sometimes every value shares a bit, so no piece can score 0.
  const shared = mode < 0.2 ? 1 << Math.floor(rand() * 4) : 0;
  const top = mode < 0.6 ? (size === 'large' ? 999990 : 8) : (size === 'large' ? 16 : 999990);
  return [Array.from({ length: n }, () => Math.floor(rand() * top) | shared)];
}
